"""The public conversion API."""
from __future__ import annotations

import io
import os
from dataclasses import dataclass, field
from typing import List, Optional

from .document import parse_document
from .fonts import FontManager
from .layout import Flow, Layouter
from .oxml import Package
from .render import Renderer


@dataclass
class Result:
    """What a conversion produced."""
    pages: int = 0
    warnings: List[str] = field(default_factory=list)
    missing_fonts: List[str] = field(default_factory=list)
    output: Optional[str] = None

    def __bool__(self):
        return self.pages > 0


class Converter:
    """Reusable converter; keeps the font index warm between documents."""

    def __init__(self, font_dirs=None, default_font='Calibri', font_cache=True,
                 **options):
        self.options = dict(options)
        self.options.setdefault('default_font', default_font)
        self.options.setdefault('font_dirs', font_dirs)
        self.options.setdefault('font_cache', font_cache)
        self.fonts = FontManager(extra_dirs=font_dirs, use_cache=font_cache,
                                 default_family=default_font)

    def convert(self, source, target=None, context=None, **overrides):
        """Convert a .docx to PDF.

        *source* is a path, bytes or file-like object; *target* a path or
        file-like object (omit it to get the PDF back as bytes).  Pass
        *context* to fill ``{{ placeholders }}`` in the document first.
        """
        options = dict(self.options)
        options.update(overrides)
        if context is not None:
            from .templates import render_docx
            source = render_docx(source, context, jinja=options.get('jinja', True))
        package = source if isinstance(source, Package) else Package(source)
        document = parse_document(package, options)
        self.fonts.strategy = options.get('font_fallback', self.fonts.strategy)
        self.fonts.set_document_default(_document_font(document, options))
        layouter = Layouter(document, fonts=self.fonts, options=options)
        pages = Flow(layouter, options).run()
        renderer = Renderer(pages, document, options)

        result = Result(pages=len(pages))
        if target is None:
            buffer = io.BytesIO()
            renderer.write(buffer)
            data = buffer.getvalue()
        else:
            if hasattr(target, 'write'):
                renderer.write(target)
                data = None
            else:
                target = os.fspath(target)
                directory = os.path.dirname(os.path.abspath(target))
                if directory:
                    os.makedirs(directory, exist_ok=True)
                renderer.write(target)
                result.output = target
                data = None
        result.warnings = list(document.warnings) + list(layouter.warnings) \
            + list(renderer.warnings)
        result.missing_fonts = sorted(self.fonts.missing_families)
        self.last_result = result
        if target is None:
            return data
        return result


def _document_font(document, options) -> str:
    """The font Word would fall back to for this document."""
    override = options.get('default_font_override')
    if override:
        return override
    styles = document.styles
    if styles is not None:
        family = styles.doc_rpr.font_ascii
        if not family and styles.doc_rpr.theme_ascii and styles.theme is not None:
            family = styles.theme.font(styles.doc_rpr.theme_ascii)
        normal = styles.get(styles.default_para_style)
        if not family and normal is not None:
            family = normal.rpr.font_ascii
        if not family and styles.theme is not None:
            family = styles.theme.minor_font
        if family:
            return family
    return options.get('default_font', 'Calibri')


_default: Optional[Converter] = None


def _converter(**options) -> Converter:
    global _default
    keys = ('font_dirs', 'default_font', 'font_cache')
    if _default is None or any(options.get(k) not in (None, _default.options.get(k))
                               for k in keys if k in options):
        _default = Converter(font_dirs=options.get('font_dirs'),
                             default_font=options.get('default_font', 'Calibri'),
                             font_cache=options.get('font_cache', True))
    return _default


def convert(source, target=None, context=None, **options):
    """Convert a .docx file to PDF without Word or LibreOffice.

    >>> convert('report.docx', 'report.pdf')
    >>> pdf_bytes = convert('report.docx')
    >>> convert('invoice.docx', 'invoice.pdf', context={'total': '12.00'})
    """
    converter = _converter(**options)
    return converter.convert(source, target, context=context, **options)


def convert_to_bytes(source, context=None, **options) -> bytes:
    return convert(source, None, context=context, **options)


def convert_many(sources, out_dir='.', **options):
    """Convert several documents, reusing one warm font index."""
    converter = _converter(**options)
    results = []
    for source in sources:
        name = os.path.splitext(os.path.basename(os.fspath(source)))[0] + '.pdf'
        results.append(converter.convert(source, os.path.join(out_dir, name),
                                         **options))
    return results
